func TestProviderFunctions_protoV5MuxServer(t *testing.T) {
	t.Parallel()

	ctx := context.Background()
	providerFn, err := acctest.MuxedProviders(t.Name())
	if err != nil {
		t.Fatalf("MuxedProviders failed: %v", err)
	}
	srv := providerFn()

	schemaResp, err := srv.GetProviderSchema(ctx, &tfprotov5.GetProviderSchemaRequest{})
	if err != nil {
		t.Fatalf("GetProviderSchema failed: %v", err)
	}

	expectedFunctions := []string{
		"location_from_id",
		"name_from_id",
		"project_from_id",
		"region_from_id",
		"region_from_zone",
		"zone_from_id",
	}
	for _, fnName := range expectedFunctions {
		fnSchema, ok := schemaResp.Functions[fnName]
		if !ok {
			t.Fatalf("expected function %q to be registered in muxed GetProviderSchema", fnName)
		}
		if len(fnSchema.Parameters) != 1 || !fnSchema.Parameters[0].Type.Is(tftypes.String) {
			t.Fatalf("function %q expected 1 string parameter, got %+v", fnName, fnSchema.Parameters)
		}
		if fnSchema.Return == nil || !fnSchema.Return.Type.Is(tftypes.String) {
			t.Fatalf("function %q expected string return, got %+v", fnName, fnSchema.Return)
		}
	}

	testCases := []struct {
		name    string
		fn      string
		arg     string
		want    string
		wantErr string
	}{
		{
			name: "location_from_id valid",
			fn:   "location_from_id",
			arg:  "projects/my-project/locations/us-central1/services/my-service",
			want: "us-central1",
		},
		{
			name:    "location_from_id invalid",
			fn:      "location_from_id",
			arg:     "projects/my-project/zones/us-central1-a/instances/my-instance",
			wantErr: `doesn't contain the expected pattern "locations/{location}/"`,
		},
		{
			name: "name_from_id valid",
			fn:   "name_from_id",
			arg:  "projects/my-project/topics/tf-test-name-id-func",
			want: "tf-test-name-id-func",
		},
		{
			name:    "name_from_id invalid",
			fn:      "name_from_id",
			arg:     "invalid-unslashed-id",
			wantErr: `doesn't contain the expected pattern "resourceType/{name}$"`,
		},
		{
			name: "project_from_id valid",
			fn:   "project_from_id",
			arg:  "projects/my-project/topics/my-topic",
			want: "my-project",
		},
		{
			name:    "project_from_id invalid",
			fn:      "project_from_id",
			arg:     "organizations/123456789/locations/global",
			wantErr: `doesn't contain the expected pattern "projects/{project}/"`,
		},
		{
			name: "region_from_id valid",
			fn:   "region_from_id",
			arg:  "projects/my-project/regions/us-central1/nodeTemplates/my-template",
			want: "us-central1",
		},
		{
			name:    "region_from_id invalid",
			fn:      "region_from_id",
			arg:     "projects/my-project/zones/us-central1-a/disks/my-disk",
			wantErr: `doesn't contain the expected pattern "regions/{region}/"`,
		},
		{
			name: "region_from_zone multi-hyphen valid",
			fn:   "region_from_zone",
			arg:  "northamerica-northeast1-b",
			want: "northamerica-northeast1",
		},
		{
			name:    "region_from_zone invalid",
			fn:      "region_from_zone",
			arg:     "invalidzone",
			wantErr: `is not a valid zone name`,
		},
		{
			name:    "region_from_zone empty",
			fn:      "region_from_zone",
			arg:     "",
			wantErr: `cannot be empty`,
		},
		{
			name: "zone_from_id valid",
			fn:   "zone_from_id",
			arg:  "projects/my-project/zones/us-central1-a/disks/my-disk",
			want: "us-central1-a",
		},
		{
			name:    "zone_from_id invalid",
			fn:      "zone_from_id",
			arg:     "projects/my-project/regions/us-central1/subnetworks/my-subnet",
			wantErr: `doesn't contain the expected pattern "zones/{zone}/"`,
		},
	}

	for _, tc := range testCases {
		t.Run(tc.name, func(t *testing.T) {
			argVal, err := tfprotov5.NewDynamicValue(tftypes.String, tftypes.NewValue(tftypes.String, tc.arg))
			if err != nil {
				t.Fatalf("NewDynamicValue failed: %v", err)
			}
			resp, err := srv.CallFunction(ctx, &tfprotov5.CallFunctionRequest{
				Name:      tc.fn,
				Arguments: []*tfprotov5.DynamicValue{&argVal},
			})
			if err != nil {
				t.Fatalf("CallFunction(%q) returned RPC error: %v", tc.fn, err)
			}
			if tc.wantErr != "" {
				if resp.Error == nil {
					t.Fatalf("CallFunction(%q, %q) expected error containing %q, got nil", tc.fn, tc.arg, tc.wantErr)
				}
				if !strings.Contains(resp.Error.Text, tc.wantErr) {
					t.Fatalf("CallFunction(%q, %q) error = %q, want substring %q", tc.fn, tc.arg, resp.Error.Text, tc.wantErr)
				}
				return
			}
			if resp.Error != nil {
				t.Fatalf("CallFunction(%q, %q) unexpected error: %s", tc.fn, tc.arg, resp.Error.Text)
			}
			val, err := resp.Result.Unmarshal(tftypes.String)
			if err != nil {
				t.Fatalf("Result.Unmarshal failed: %v", err)
			}
			var got string
			if err := val.As(&got); err != nil {
				t.Fatalf("val.As(&got) failed: %v", err)
			}
			if got != tc.want {
				t.Fatalf("CallFunction(%q, %q) = %q, want %q", tc.fn, tc.arg, got, tc.want)
			}
		})
	}
}
